|     ~Cat() {
|         delete snacks;
|         cout << name << " 走啦，仓库还回去" << endl;
|     }
| };
| void kitchen() {
|     Cat tmp("狸花", 1);
|     cout << "厨房里现在有一只 " << tmp.name << endl;
