#include <stdio.h>

enum Kind { IS_INT, IS_DOUBLE };

struct Value {
    enum Kind kind;
    union {
        int i;
        double d;
    } num;
};

int main(void) {
    int k;
    int n;
    struct Value v;

    if (scanf("%d", &k) != 1) {
        return 1;
