int cap = 25;        /* ── 最外面那层地盘上的碗 ── */

void report(void) {
    int cap = 39;    /* ── 招式里的碗 ── */

    /* ── 请在这儿自己画一个花括号的圈：圈里再摆一只同名的碗（装 9），
          在圈里印一行 `圈里 <那只碗装的数>`，出了圈再印一行
          `出圈之后 <这一层那只碗装的数>` ── */

}

int main(void) {
    report();
    printf("外面地盘 %d\n", cap);
    return 0;
}

