#include <stdio.h>

int sum(int a[], int n) {
    if (n == 0) {
        return 0;
    }
    return a[n - 1] + sum(a, n - 1);
}

int main(void) {
    int nums[4];

    for (int i = 0; i < 4; i++) {
        if (scanf("%d", &nums[i]) != 1) {
            return 1;
        }
    }

    printf("一共 %d 条喵\n", sum(nums, 4));
    return 0;
}

