想把前面的留住，第二次要用 `"a"`：

```c
#include <stdio.h>

int main(void) {
    FILE *fp = fopen("dangan.txt", "w");
    fprintf(fp, "第一天 3 条\n");
    fclose(fp);

    fp = fopen("dangan.txt", "a");
    fprintf(fp, "第二天 5 条\n");
    fclose(fp);

    fp = fopen("dangan.txt", "r");
