#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int *fish = malloc(sizeof(int) * n);
    if (fish == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &fish[i]) != 1) {
            free(fish);
            return 1;
        }
    }

    int total = 0;
    for (int i = n - 1; i >= 0; i--) {
        printf("第 %d 号收 %d 条喵\n", i + 1, fish[i]);
        total = total + fish[i];
    }
    printf("一共 %d 条喵\n", total);

    free(fish);
    return 0;
}

