/* 理牌式：一张一张摸进来，往左找位子，路上把大牌往右挤 */
void insert_card(int a[], int n) {
    for (int i = 1; i < n; i++) {
        int key = a[i];
        int j = i - 1;
        while (j >= 0 && a[j] > key) {
            a[j + 1] = a[j];
            j--;
