#include <stdio.h>

/* 把 a 里 lo..mid 和 mid+1..hi 两摊各自排好的数，合起来成从小到大的一摊 */
void join(int a[], int lo, int mid, int hi) {
    int tmp[128];
    int i = lo;
    int j = mid + 1;
    int k = 0;

    while (i <= mid && j <= hi) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
        }
    }
    while (i <= mid) {
        tmp[k++] = a[i++];
    }
    while (j <= hi) {
        tmp[k++] = a[j++];
    }

    for (int x = 0; x < k; x++) {
        a[lo + x] = tmp[x];
    }
}

