#include <stdio.h>
#include <string.h>

int naive(const char *text, const char *pat) {
    int n = (int)strlen(text);
    int m = (int)strlen(pat);
    int tries = 0;
    for (int i = 0; i + m <= n; i++) {
        int j = 0;
        while (j < m) {
            tries++;
            if (text[i + j] != pat[j]) {
                break;
            }
            j++;
        }
        if (j == m) {
            return tries;
        }
    }
    return -tries;
}

void build_book(const char *pat, int *book) {
    int m = (int)strlen(pat);
    book[0] = 0;
    for (int i = 1; i < m; i++) {
        int k = book[i - 1];
        while (k > 0 && pat[i] != pat[k]) {
            k = book[k - 1];
        }
        if (pat[i] == pat[k]) {
            k++;
        }
        book[i] = k;
    }
}

int kmp(const char *text, const char *pat) {
    int n = (int)strlen(text);
    int m = (int)strlen(pat);
    int book[64];
    build_book(pat, book);

    int tries = 0;
    int k = 0;
    for (int i = 0; i < n; i++) {
        while (k > 0 && text[i] != pat[k]) {
            k = book[k - 1];
        }
        tries++;
        if (text[i] == pat[k]) {
            k++;
        }
        if (k == m) {
            return tries;
        }
    }
    return -tries;
}

int main(void) {
    const char *text = "ababababc";
    const char *pat = "ababc";

    int book[64];
    build_book(pat, book);
    printf("小本本：");
    for (int i = 0; i < (int)strlen(pat); i++) {
        printf("%d ", book[i]);
