/* 小本本：记下「已经对上的这一段」里，头上能对上的最长一段有多长 */
void build_book(const char *pat, int *book) {
    int m = (int)strlen(pat);
    book[0] = 0;
    for (int i = 1; i < m; i++) {
        int k = book[i - 1];
        while (k > 0 && pat[i] != pat[k]) {
            k = book[k - 1];          /* 这个长度也不行，退回更短的那个 */
        }
        if (pat[i] == pat[k]) {
            k++;
        }
        book[i] = k;
    }
}

/* 带着小本本对：崩了不回起点，退到小本本上记的那个长度接着对 */
int kmp(const char *text, const char *pat) {
    int n = (int)strlen(text);
    int m = (int)strlen(pat);
    int book[64];
    build_book(pat, book);

    int tries = 0;
    int k = 0;                        /* 已经对上了几颗 */
    for (int i = 0; i < n; i++) {
        while (k > 0 && text[i] != pat[k]) {
            k = 0;                    /* 崩了：退回起点 */
        }
        tries++;
        if (text[i] == pat[k]) {
            k++;
        }
        if (k == m) {
            return tries;             /* 整段都对上了 */
        }
    }
    return -tries;
}

int main(void) {
    const char *text = "aaaaaaab";
    const char *pat = "aaab";

    int book[64];
    build_book(pat, book);
    printf("小本本：");
    for (int i = 0; i < (int)strlen(pat); i++) {
        printf("%d ", book[i]);
    }
    printf("\n");

    int b = kmp(text, pat);
    if (b < 0) {
        printf("带着小本本也没找着\n");
    } else {
        printf("带着小本本只比了 %d 次\n", b);
    }
    return 0;
}

