questions.referenceSolution:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    srand(5);
    int secret = rand() % 100 + 1;   /* 骰子想好的秘密，已经给你了 */

    int g;
    int times = 0;
    while (scanf("%d", &g) == 1) {
        times++;
        if (g < secret) {
            printf("猜 %d：小了\n", g);
        } else if (g > secret) {
            printf("猜 %d：大了\n", g);
        } else {
            printf("猜 %d：猜中啦，一共猜了 %d 次\n", g, times);
            return 0;
        }
    }

    printf("%d 次都没猜中\n", times);
    return 0;
}

