questions.referenceSolution:
#include <stdio.h>

void print_report(int fish[], int count) {
    if (count <= 0) {
        printf("没有碗喵\n");
        return;
    }
    int total = 0;
    for (int i = 0; i < count; i++) {
        total += fish[i];
        printf("第 %d 碗：%d 条\n", i + 1, fish[i]);
    }
    printf("合计：%d 条\n", total);
}

int main(void) {
    int fish[3] = { 2, 3, 4 };
    print_report(fish, 3);
    print_report(fish, 0);
    return 0;
}

