#include <stdio.h>

int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int bowls[64];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bowls[i]) != 1) {
            return 1;
        }
    }

    for (int round = 0; round < n - 1; round++) {
        for (int i = 0; i < n - 1 - round; i++) {
            if (bowls[i] > bowls[i + 1]) {
                int t = bowls[i];
                bowls[i] = bowls[i + 1];
                bowls[i + 1] = t;
            }
        }
    }

    for (int i = 0; i < n; i++) {
        printf("%d\n", bowls[i]);
    }

    int kinds = 1;
    for (int i = 1; i < n; i++) {
        if (bowls[i] != bowls[i - 1]) {
            kinds = kinds + 1;
        }
    }
    printf("不同的一共 %d 种喵\n", kinds);

    return 0;
}

