int main() {
    int a = 0;
    int b = 0;
    int c = 0;
    cin >> a >> b >> c;

    Cat c1("小橘", a);
    Cat c2("狸花", b);
    c1.addFish(c);
    cout << c1.getName() << " 有 " << c1.getFish() << " 条" << endl;
    cout << c2.getName() << " 有 " << c2.getFish() << " 条" << endl;
    return 0;
}

