    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        l.push_back(x);
    }

    int i = 0;
    for (auto it = l.begin(); it != l.end(); ++it) {
        cout << "第 " << i << " 格有 " << *it << " 条喵" << endl;
        i++;
    }
    return 0;
}

