#include <iostream>
#include <vector>

/* 分堆：拿最后一只当尺子，比它矮的换到左边，比它高的留在右边，尺子站到中线上 */
int partition(std::vector<int>& a, int lo, int hi) {
    int pivot = a[hi];
    int i = lo;

    for (int j = lo; j < hi; j++) {
