#include <iostream>
#include <vector>

const int SLOTS = 10;

std::vector<int> shelf(SLOTS, 0);
std::vector<int> used(SLOTS, 0);

/* 按编号算门牌号 */
int slot_of(int id) {
    return id ____ SLOTS;
}

void put(int id) {
    int slot = slot_of(id);
    while (used[slot]) {
        slot = (slot + ____) % SLOTS;
    }
    shelf[slot] = id;
    used[slot] = 1;
}

