#include <iostream>
#include <string>
using namespace std;

int stock = 10;

void take(int n) {
    if (n > stock) {
        throw string("不够了");
    }
    stock -= n;
    cout << "领走 " << n << "，还剩 " << stock << endl;
}

int main() {
    try {
        take(5);
    } catch (string e) {
        cout << "接住：" << e << endl;
    }

    try {
        take(100);
    } catch (string e) {
        cout << "接住：" << e << endl;
    }

    cout << "仓库里还是 " << stock << endl;
    return 0;
}

