#include <string>
using namespace std;

class Cat {
public:
    string name;
    Cat(const string& n) : name(n) {}
    virtual ~Cat() {}
};

class OrangeCat : public Cat {
public:
    OrangeCat(const string& n) : Cat(n) {}
};

class TabbyCat : public Cat {
public:
    TabbyCat(const string& n) : Cat(n) {}
};

int main() {
    int kind = 0;
    cin >> kind;

    OrangeCat o("小橘");
    TabbyCat t("狸花");
    Cat* p = &t;
    if (kind == 1) p = &o;

    return 0;
}

questions.referenceSolution:
#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    Cat(const string& n) : name(n) {}
    virtual ~Cat() {}
};

class OrangeCat : public Cat {
public:
    OrangeCat(const string& n) : Cat(n) {}
};

class TabbyCat : public Cat {
public:
    TabbyCat(const string& n) : Cat(n) {}
};

int main() {
    int kind = 0;
    cin >> kind;

    OrangeCat o("小橘");
    TabbyCat t("狸花");
    Cat* p = &t;
    if (kind == 1) p = &o;

    OrangeCat* a = dynamic_cast<OrangeCat*>(p);
    cout << (a == nullptr ? "不是橘猫：" : "是橘猫：") << p->name << endl;
    return 0;
}

