#include <iostream>
#include <map>
using namespace std;

int main() {
    int n = 0;
    if (!(cin >> n)) {
        return 1;
    }

    map<int, int> tally;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        tally[x] = tally[x] + 1;
    }

    for (map<int, int>::iterator it = tally.begin(); it != tally.end(); ++it) {
        cout << it->first << " 来了 " << it->second << " 次喵" << endl;
    }
    cout << "一共 " << (int)tally.size() << " 位客人喵" << endl;

    return 0;
}

