/* 鱼干盘点：一边记下最大的一只，一边把总数加起来 */
int main() {
    int fish_count = 0;
    std::cin >> fish_count;

    int max_fish = 0;
    int total_fish = 0;
    for (int i = 0; i < fish_count; i++) {
        int fish_size = 0;
        std::cin >> fish_size;
        if (fish_size > max_fish) {
            max_fish = fish_size;
        }
        total_fish = total_fish + fish_size;
    }

    std::cout << "最大：" << max_fish << " 条喵" << std::endl;
