import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[] bills = new int[n];
        for (int i = 0; i < n; i++) {
            bills[i] = sc.nextInt();
        }

        int running = 0;
        for (int i = n - 1; i >= 0; i--) {
            running = running + bills[i];
            System.out.println("第 " + (i + 1) + " 号收 " + bills[i] + " 条，累计 " + running + " 条喵");
        }
        System.out.println("一共 " + running + " 条喵");
    }
}

