questions.referenceSolution:
import java.util.Scanner;

class Cat {
    private String name;
    private int fish;

    Cat(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public int getFish() {
        return fish;
    }

    public void feed(int more) {
        if (more > 3) {
            System.out.println("一次最多只添 3 条喵");
            return;
        }
        fish = fish + more;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Cat c = new Cat("小橘");
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            c.feed(sc.nextInt());
        }
        System.out.println(c.getName() + " 账上 " + c.getFish() + " 条小鱼干喵");
    }
}

