    private String name;
    private int fish;

    Cat(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public int getFish() {
        return fish;
    }

    public void setFish(int fish) {
        if (fish < 0) {
            System.out.println("鱼干数不能是负的喵");
            return;
        }
        this.fish = fish;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Cat c = new Cat("狸花");
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            c.setFish(sc.nextInt());
        }
        System.out.println(c.getName() + " 有 " + c.getFish() + " 条小鱼干喵");
    }
}

