        super(name);
        this.fish = fish;
    }

    void report() {
        System.out.println(getName() + " 有 " + fish + " 条小鱼干喵");
    }
}

public class Main {
    public static void main(String[] args) {
        Cat c = new Cat("狸花", 7);
        c.report();
    }
}

