questions.referenceSolution:
import java.util.Scanner;

interface Greeter {
    void greet();

    default void greetMany() {
        for (int i = 0; i < 2; i++) {
            greet();
        }
    }
}

class Cat implements Greeter {
    String name;

    Cat(String name) {
        this.name = name;
    }

    @Override
    public void greet() {
        System.out.println(name + "：喵～");
    }
}

class Robot implements Greeter {
    String name;

    Robot(String name) {
        this.name = name;
    }

    @Override
    public void greet() {
        System.out.println(name + "：嘀嘀");
    }

    @Override
    public void greetMany() {
        greet();
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int rounds = sc.nextInt();
        Greeter cat = new Cat("小橘");
        Greeter robot = new Robot("铁喵");
        for (int r = 0; r < rounds; r++) {
            cat.greetMany();
            robot.greetMany();
        }
    }
}

