import java.util.Scanner;

class Cat {
    static final int MAX_FISH = 4;
    String name;

    Cat(String name) {
        this.name = name;
    }

    void eat(int fish) {
        if (fish > MAX_FISH) {
            System.out.println(name + "：太多啦，最多 " + MAX_FISH + " 条");
        } else {
            System.out.println(name + "：吃了 " + fish + " 条");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Cat a = new Cat("小橘");
        for (int i = 0; i < n; i++) {
            int fish = sc.nextInt();
            a.eat(fish);
        }
        System.out.println("规矩是 " + Cat.MAX_FISH + " 条");
    }
}

