questions.referenceSolution:
import java.util.Scanner;

public class Main {
    enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }

    interface Judge {
        boolean ok(Day d);
    }

    static boolean report(Day d, Judge j) {
        if (j.ok(d)) {
            System.out.println(d.name() + " 合格");
            return true;
        }
        System.out.println(d.name() + " 不合格");
        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            if (report(Day.values()[sc.nextInt()], new Judge() {
                @Override
                public boolean ok(Day d) {
                    return d.ordinal() % 2 == 0;
                }
            })) {
                cnt++;
            }
        }
        System.out.println("合格的一共 " + cnt + " 天");
    }
}

