questions.referenceSolution:
import java.util.ArrayList;
import java.util.List;

class Person {
    private String name;

    Person(String name) {
        this.name = name;
    }

    String intro() {
        return "本喵叫 " + name;
    }
}

class Student extends Person {
    private int score;

    Student(String name, int score) {
        super(name);
        this.score = score;
    }

    int getScore() { return score; }

    @Override
    String intro() {
        return super.intro() + "，考了 " + score + " 分";
    }
}

public class Main {
    public static void main(String[] args) {
        List<Person> mingdan = new ArrayList<>();
        mingdan.add(new Person("小黑"));
        mingdan.add(new Student("小虎", 86));
        mingdan.add(new Student("花花", 90));
        for (int i = 0; i < mingdan.size(); i++) {
            System.out.println((i + 1) + ". " + mingdan.get(i).intro());
        }
        System.out.println("名单上一共 " + mingdan.size() + " 只");
    }
}

