questions.referenceSolution:
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static double total(List<? extends Number> box) {
        double sum = 0;
        for (Number x : box) {
            sum = sum + x.doubleValue();
        }
        return sum;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Integer> nums = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            nums.add(sc.nextInt());
        }
        System.out.println("柜子里有 " + nums.size() + " 件");
        System.out.println("加起来是 " + total(nums));
    }
}

