import java.util.Scanner;

public class Main {
    // 把 a 里 lo..mid 和 mid+1..hi 两摊各自排好的数，合起来成从小到大的一摊
    static void join(int[] a, int lo, int mid, int hi) {
        int[] tmp = new int[128];
        int i = lo;
        int j = mid + 1;
        int k = 0;

        while (i <= mid && j <= hi) {
            if (a[i] <= a[j]) {
                tmp[k++] = a[i++];
            } else {
                tmp[k++] = a[j++];
            }
        }
        while (i <= mid) {
            tmp[k++] = a[i++];
        }
        while (j <= hi) {
            tmp[k++] = a[j++];
        }

        for (int x = 0; x < k; x++) {
            a[lo + x] = tmp[x];
        }
    }

    // 上一课那一招：把 a 里 lo..hi 这一段排成从小到大
    static void sortHalf(int[] a, int lo, int hi) {
        for (int i = lo; i < hi; i++) {
            for (int j = lo; j < hi - (i - lo); j++) {
                if (a[j] > a[j + 1]) {
                    int t = a[j];
                    a[j] = a[j + 1];
                    a[j + 1] = t;
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[64];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int mid = (n - 1) / 2;
        sortHalf(a, 0, mid);
        sortHalf(a, mid + 1, n - 1);
        join(a, 0, mid, n - 1);

        System.out.print("合起来：");
        for (int i = 0; i < n; i++) {
            System.out.print(a[i] + " ");
        }
        System.out.println();
    }
}

