public class Main {
    static void join(int[] a, int lo, int mid, int hi) {
        int[] tmp = new int[128];
        int i = lo;
        int j = mid + 1;
        int k = 0;

        while (i <= mid && j <= hi) {
            if (a[i] <= a[j]) {
                tmp[k++] = a[i++];
            } else {
                tmp[k++] = a[j++];
            }
        }
        while (i <= mid) {
            tmp[k++] = a[i++];
        }
        while (j <= hi) {
            tmp[k++] = a[j++];
        }

        for (int x = 0; x < k; x++) {
            a[lo + x] = tmp[x];
        }
    }

    public static void main(String[] args) {
        int[] a = {40, 50, 80, 90, 10, 20, 60, 70};
        join(a, 0, 3, 7);

        System.out.print("合并法：");
        for (int i = 0; i < 8; i++) {
            System.out.print(a[i] + " ");
        }
        System.out.println();
    }
}

