import java.util.Scanner;

public class Main {
    // 分堆：拿最后一只当尺子，比它矮的换到左边，比它高的留在右边，尺子站到中线上
    static int partition(int[] a, int lo, int hi) {

        // ① 把最后一只的值抄下来当尺子（别拿位子，抄值）
        // ② 从 lo 往后看：比尺子矮的，换到左边那条线的下一位，线往右挪一格
        // ③ 走完之后，把尺子换到那条线上
        // ④ 把尺子现在站的位子答回去
        return 0;
    }

    static void quick(int[] a, int lo, int hi) {
        if (lo >= hi) {
            return;
        }
        int p = partition(a, lo, hi);
        quick(a, lo, p - 1);
        quick(a, p + 1, hi);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[64];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        quick(a, 0, n - 1);

        System.out.print("尺子法：");
        for (int i = 0; i < n; i++) {
            System.out.print(a[i] + " ");
        }
        System.out.println();
    }
}

