public class Main {
    /* 砍一半：每次先看正中间那只，答「比了几次」；没找到就答负数 */
    static <T extends Comparable<T>> int half_find(T[] fish, T target) {
        int lo = 0;
        int hi = ____;
        int tries = 0;

        while (lo <= hi) {
            int mid = (lo + hi) / ____;
            tries++;
            if (fish[mid].compareTo(target) == 0) {
                return tries;
            } else if (fish[mid].compareTo(target) < 0) {
                lo = mid + ____;
            } else {
                hi = mid - 1;
            }
        }
        return -tries;
    }

    public static void main(String[] args) {
        Integer[] fish = {1, 3, 5, 7, 9, 11, 13};
        int a = half_find(fish, 13);
        int b = half_find(fish, 6);
        System.out.println("找 13：比了 " + (a < 0 ? -a : a) + " 次" + (a < 0 ? "没找到" : ""));
        System.out.println("找 6：比了 " + (b < 0 ? -b : b) + " 次" + (b < 0 ? "没找到" : ""));
    }
}

public class Main {
    static final int SLOTS = 10;

    static int[] shelf = new int[SLOTS];
    static boolean[] used = new boolean[SLOTS];

    /* 按编号算门牌号 */
    static int slot_of(int id) {
        return id ____ SLOTS;
    }

    static void put(int id) {
        int slot = slot_of(id);
        while (used[slot]) {
            slot = (slot + ____) % SLOTS;
        }
        shelf[slot] = id;
        used[slot] = true;
    }

    public static void main(String[] args) {
        put(7);
        put(17);
        System.out.println("17 住在第 " + (slot_of(17) + 1) + " 格");
    }
}

public class Main {
    static <T extends Comparable<T>> int line_find(T[] fish, T target) {
        int tries = 0;
        for (int i = 0; i < fish.length; i++) {
            tries++;
            if (fish[i].compareTo(target) == 0) {
                return tries;
            }
        }
        return -tries;
    }

    static <T extends Comparable<T>> int half_find(T[] fish, T target) {
        int lo = 0;
        int hi = fish.length - 1;
        int tries = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            tries++;
            if (fish[mid].compareTo(target) == 0) {
                return tries;
            } else if (fish[mid].compareTo(target) < 0) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return -tries;
    }

    public static void main(String[] args) {
        Integer[] fish = {2, 4, 6, 8, 10};
        Integer[] targets = {10, 2};
        for (int i = 0; i < targets.length; i++) {
            Integer t = targets[i];
            int a = line_find(fish, t);
