public class Main {
    static final int SLOTS = 10;

    static int[] shelf = new int[SLOTS];
    static boolean[] used = new boolean[SLOTS];

    static int slot_of(int id) {
        return id % SLOTS;
    }

    static void put(int id) {
        int slot = slot_of(id);
        while (used[slot]) {
            slot = (slot + 1) % SLOTS;
        }
        shelf[slot] = id;
        used[slot] = true;
    }

    static int find(int id) {
        int slot = slot_of(id);
        int tries = 0;
        while (used[slot]) {
            tries++;
            if (shelf[slot] == id) {
                return tries;
            }
            slot = (slot + 1) % SLOTS;
        }
        return 0;
    }

    public static void main(String[] args) {
        put(4);
        put(14);
        put(6);

        System.out.println("找 14：比了 " + find(14) + " 次");
        System.out.println("找 6：比了 " + find(6) + " 次");
        System.out.println("找 9：比了 " + find(9) + " 次");
    }
}

