    // 挨着看：从第一只开始一只只比过去，答「比了几次」；一只都没对上就答负数
    static int lineFind(int[] a, int n, int target) {
        int tries = 0;
        for (int i = 0; i < n; i++) {
            tries++;
            if (a[i] == target) {
                return tries;
            }
        }
        return -tries;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int target = sc.nextInt();
        int[] a = new int[64];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int times = lineFind(a, n, target);
        if (times < 0) {
            System.out.println("挨着看：没找到");
        } else {
            System.out.println("挨着看：比了 " + times + " 次");
        }
    }
}

