class Fish implements Serializable {
    String 名字;
    transient int 条数 = 7;

    Fish(String 名字) {
        this.名字 = 名字;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Fish 原猫 = new Fish("小橘");

        ObjectOutputStream 出口 = new ObjectOutputStream(new FileOutputStream("猫.bin"));
