import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] 份数 = new int[n];
        for (int i = 0; i < n; i++) {
            份数[i] = sc.nextInt();
        }

        Cat[] 一队 = new Cat[n];
        for (int i = 0; i < n; i++) {
            一队[i] = new Cat(份数[i]);
        }
        for (int i = 0; i < n; i++) {
            一队[i].start();
