import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    static class 大猫 {
        @Deprecated
        void 老招呼() {
        }

        @Deprecated
        void 老舔毛() {
        }

        void 新招呼() {
        }
    }

    public static void main(String[] args) throws Exception {
        List<String> 表 = new ArrayList<>();
        int 过时的 = 0;
        for (Method 一招 : 大猫.class.getDeclaredMethods()) {
            if (一招.isAnnotationPresent(Deprecated.class)) {
                过时的 = 过时的 + 1;
                表.add(一招.getName() + "：已过时");
            } else {
                表.add(一招.getName() + "：还在用");
            }
        }
        Collections.sort(表);
        for (String 一行 : 表) {
            System.out.println(一行);
        }
        System.out.println("过时的一共 " + 过时的 + " 招");
    }
}

