public class Main {
    public static void main(String[] args) {
        账本 甲 = 账本.拿本();
        账本 乙 = 账本.拿本();
        甲.添(2);
        System.out.println("是同一本吗：" + (甲 == 乙));
        System.out.println("乙 里看到的条数：" + 乙.条数);
    }
}

class 账本 {
    private static 账本 唯一的一本;

    int 条数;

    private 账本() {
    }

    static 账本 拿本() {
        if (唯一的一本 == null) {
            唯一的一本 = new 账本();
        }
        return 唯一的一本;
    }

    void 添(int 几条) {
        条数 = 条数 + 几条;
    }
}

