        ServerSocket 门 = new ServerSocket(0, 50, InetAddress.getByName("127.0.0.1"));
        int 端口 = 门.getLocalPort();

        Thread 守门的 = new Thread(() -> {
            try {
                while (true) {
                    Socket 客 = 门.accept();
                    new Thread(() -> 陪着一位(客)).start();
