questions.referenceSolution:
BOWL_LIMIT = 6


def count_total(nums):
    total = 0
    for amount in nums:
        total = total + amount
    return total


def has_over(nums):
    for amount in nums:
        if amount > BOWL_LIMIT:
            return True
    return False


n = int(input())
nums = []
for i in range(n):
    nums.append(int(input()))
total = count_total(nums)
average = total // n
print("总共", total, "条")
print("平均", average, "条")
if has_over(nums):
    print("有碗超限了")
else:
    print("碗都在限内")

